import numpy as np
ADJUGATE_TERMS = [[[1, [[1, 1], [2, 2], [3, 3]]], [-1, [[1, 1], [2, 3], [3, 2]]], [-1, [[2, 1], [1, 2], [3, 3]]], [1, [[2, 1], [1, 3], [3, 2]]], [1, [[3, 1], [1, 2], [2, 3]]], [-1, [[3, 1], [1, 3], [2, 2]]]], [[-1, [[0, 1], [2, 2], [3, 3]]], [1, [[0, 1], [2, 3], [3, 2]]], [1, [[2, 1], [0, 2], [3, 3]]], [-1, [[2, 1], [0, 3], [3, 2]]], [-1, [[3, 1], [0, 2], [2, 3]]], [1, [[3, 1], [0, 3], [2, 2]]]], [[1, [[0, 1], [1, 2], [3, 3]]], [-1, [[0, 1], [1, 3], [3, 2]]], [-1, [[1, 1], [0, 2], [3, 3]]], [1, [[1, 1], [0, 3], [3, 2]]], [1, [[3, 1], [0, 2], [1, 3]]], [-1, [[3, 1], [0, 3], [1, 2]]]], [[-1, [[0, 1], [1, 2], [2, 3]]], [1, [[0, 1], [1, 3], [2, 2]]], [1, [[1, 1], [0, 2], [2, 3]]], [-1, [[1, 1], [0, 3], [2, 2]]], [-1, [[2, 1], [0, 2], [1, 3]]], [1, [[2, 1], [0, 3], [1, 2]]]], [[-1, [[1, 0], [2, 2], [3, 3]]], [1, [[1, 0], [2, 3], [3, 2]]], [1, [[2, 0], [1, 2], [3, 3]]], [-1, [[2, 0], [1, 3], [3, 2]]], [-1, [[3, 0], [1, 2], [2, 3]]], [1, [[3, 0], [1, 3], [2, 2]]]], [[1, [[0, 0], [2, 2], [3, 3]]], [-1, [[0, 0], [2, 3], [3, 2]]], [-1, [[2, 0], [0, 2], [3, 3]]], [1, [[2, 0], [0, 3], [3, 2]]], [1, [[3, 0], [0, 2], [2, 3]]], [-1, [[3, 0], [0, 3], [2, 2]]]], [[-1, [[0, 0], [1, 2], [3, 3]]], [1, [[0, 0], [1, 3], [3, 2]]], [1, [[1, 0], [0, 2], [3, 3]]], [-1, [[1, 0], [0, 3], [3, 2]]], [-1, [[3, 0], [0, 2], [1, 3]]], [1, [[3, 0], [0, 3], [1, 2]]]], [[1, [[0, 0], [1, 2], [2, 3]]], [-1, [[0, 0], [1, 3], [2, 2]]], [-1, [[1, 0], [0, 2], [2, 3]]], [1, [[1, 0], [0, 3], [2, 2]]], [1, [[2, 0], [0, 2], [1, 3]]], [-1, [[2, 0], [0, 3], [1, 2]]]], [[1, [[1, 0], [2, 1], [3, 3]]], [-1, [[1, 0], [2, 3], [3, 1]]], [-1, [[2, 0], [1, 1], [3, 3]]], [1, [[2, 0], [1, 3], [3, 1]]], [1, [[3, 0], [1, 1], [2, 3]]], [-1, [[3, 0], [1, 3], [2, 1]]]], [[-1, [[0, 0], [2, 1], [3, 3]]], [1, [[0, 0], [2, 3], [3, 1]]], [1, [[2, 0], [0, 1], [3, 3]]], [-1, [[2, 0], [0, 3], [3, 1]]], [-1, [[3, 0], [0, 1], [2, 3]]], [1, [[3, 0], [0, 3], [2, 1]]]], [[1, [[0, 0], [1, 1], [3, 3]]], [-1, [[0, 0], [1, 3], [3, 1]]], [-1, [[1, 0], [0, 1], [3, 3]]], [1, [[1, 0], [0, 3], [3, 1]]], [1, [[3, 0], [0, 1], [1, 3]]], [-1, [[3, 0], [0, 3], [1, 1]]]], [[-1, [[0, 0], [1, 1], [2, 3]]], [1, [[0, 0], [1, 3], [2, 1]]], [1, [[1, 0], [0, 1], [2, 3]]], [-1, [[1, 0], [0, 3], [2, 1]]], [-1, [[2, 0], [0, 1], [1, 3]]], [1, [[2, 0], [0, 3], [1, 1]]]], [[-1, [[1, 0], [2, 1], [3, 2]]], [1, [[1, 0], [2, 2], [3, 1]]], [1, [[2, 0], [1, 1], [3, 2]]], [-1, [[2, 0], [1, 2], [3, 1]]], [-1, [[3, 0], [1, 1], [2, 2]]], [1, [[3, 0], [1, 2], [2, 1]]]], [[1, [[0, 0], [2, 1], [3, 2]]], [-1, [[0, 0], [2, 2], [3, 1]]], [-1, [[2, 0], [0, 1], [3, 2]]], [1, [[2, 0], [0, 2], [3, 1]]], [1, [[3, 0], [0, 1], [2, 2]]], [-1, [[3, 0], [0, 2], [2, 1]]]], [[-1, [[0, 0], [1, 1], [3, 2]]], [1, [[0, 0], [1, 2], [3, 1]]], [1, [[1, 0], [0, 1], [3, 2]]], [-1, [[1, 0], [0, 2], [3, 1]]], [-1, [[3, 0], [0, 1], [1, 2]]], [1, [[3, 0], [0, 2], [1, 1]]]], [[1, [[0, 0], [1, 1], [2, 2]]], [-1, [[0, 0], [1, 2], [2, 1]]], [-1, [[1, 0], [0, 1], [2, 2]]], [1, [[1, 0], [0, 2], [2, 1]]], [1, [[2, 0], [0, 1], [1, 2]]], [-1, [[2, 0], [0, 2], [1, 1]]]]]
DETERMINANT_TERMS = [[1, [[0, 0], [1, 1], [2, 2], [3, 3]]], [-1, [[0, 0], [1, 1], [3, 2], [2, 3]]], [-1, [[0, 0], [2, 1], [1, 2], [3, 3]]], [1, [[0, 0], [2, 1], [3, 2], [1, 3]]], [1, [[0, 0], [3, 1], [1, 2], [2, 3]]], [-1, [[0, 0], [3, 1], [2, 2], [1, 3]]], [-1, [[1, 0], [0, 1], [2, 2], [3, 3]]], [1, [[1, 0], [0, 1], [3, 2], [2, 3]]], [1, [[1, 0], [2, 1], [0, 2], [3, 3]]], [-1, [[1, 0], [2, 1], [3, 2], [0, 3]]], [-1, [[1, 0], [3, 1], [0, 2], [2, 3]]], [1, [[1, 0], [3, 1], [2, 2], [0, 3]]], [1, [[2, 0], [0, 1], [1, 2], [3, 3]]], [-1, [[2, 0], [0, 1], [3, 2], [1, 3]]], [-1, [[2, 0], [1, 1], [0, 2], [3, 3]]], [1, [[2, 0], [1, 1], [3, 2], [0, 3]]], [1, [[2, 0], [3, 1], [0, 2], [1, 3]]], [-1, [[2, 0], [3, 1], [1, 2], [0, 3]]], [-1, [[3, 0], [0, 1], [1, 2], [2, 3]]], [1, [[3, 0], [0, 1], [2, 2], [1, 3]]], [1, [[3, 0], [1, 1], [0, 2], [2, 3]]], [-1, [[3, 0], [1, 1], [2, 2], [0, 3]]], [-1, [[3, 0], [2, 1], [0, 2], [1, 3]]], [1, [[3, 0], [2, 1], [1, 2], [0, 3]]]]

def _ordered_terms(matrix, terms):
    value = None
    for sign, indices in terms:
        term = np.float32(matrix[tuple(indices[0])])
        # Initial unary minus in the C++ source precedes multiplication.
        if value is None and sign < 0:
            term = np.float32(-term)
        for index in indices[1:]:
            term = np.float32(term * matrix[tuple(index)])
        if value is None:
            value = term
        elif sign > 0:
            value = np.float32(value + term)
        else:
            value = np.float32(value - term)
    return value

def inverse_float_source_order(matrix):
    """Return inverse and intermediate scalars for a finite nonsingular 4x4.

    matrix must already be numpy.float32 with shape (4,4); do not silently
    change a caller's Double computational values. No image/sampler is used.
    """
    if not isinstance(matrix, np.ndarray) or matrix.shape != (4,4):
        raise ValueError('matrix must be a numpy array with shape (4,4)')
    if matrix.dtype != np.dtype('float32'):
        raise TypeError('matrix must explicitly be float32')
    if not np.isfinite(matrix).all():
        raise ValueError('matrix must be finite')
    determinant = _ordered_terms(matrix, DETERMINANT_TERMS)
    if determinant == np.float32(0) or not np.isfinite(determinant):
        raise ValueError('matrix has zero/nonfinite Float determinant')
    reciprocal = np.float32(np.float32(1) / determinant)
    adjugate = np.array([_ordered_terms(matrix, terms) for terms in ADJUGATE_TERMS],np.float32).reshape(4,4)
    inverse = np.float32(adjugate * reciprocal)
    if not np.isfinite(inverse).all():
        raise ValueError('Float inverse is nonfinite')
    return {'determinant':determinant, 'reciprocal':reciprocal,
            'adjugate':adjugate, 'inverse':inverse}
